function medianeDeuxTries(a, b) {
    // a and b are sorted arrays (ascending)
    const totalLen = a.length + b.length;
    const half = Math.floor((totalLen + 1) / 2);   // number of elements in the left part

    // Binary search on the partition index i in array a
    let low = Math.max(0, half - b.length);
    let high = Math.min(a.length, half);
    let mid;
    while (low <= high) {
        mid = Math.floor((low + high) / 2);
        const j = half - mid;   // partition index in array b

        // Max of the left side and min of the right side for both arrays
        let aLeftMax = (mid > 0 ? a[mid - 1] : Number.NEGATIVE_INFINITY);
        let bLeftMax = (j > 0 ? b[j - 1] : Number.NEGATIVE_INFINITY);
        let aRightMin = (mid < a.length ? a[mid] : Number.POSITIVE_INFINITY);
        let bRightMin = (j < b.length ? b[j] : Number.POSITIVE_INFINITY);

        if (aLeftMax <= aRightMin && bLeftMax <= bRightMin) {
            // Correct partition found
            break;
        } else if (aLeftMax > aRightMin || bLeftMax > bRightMin) {
            // Partition is too far to the right in array a → move left
            high = mid - 1;
        } else {
            // Partition is too far to the left in array a → move right
            low = mid + 1;
        }
    }

    // Recompute j for the final partition (mid)
    const j = half - mid;

    let aLeftMax = (mid > 0 ? a[mid - 1] : Number.NEGATIVE_INFINITY);
    let bLeftMax = (j > 0 ? b[j - 1] : Number.NEGATIVE_INFINITY);
    let aRightMin = (mid < a.length ? a[mid] : Number.POSITIVE_INFINITY);
    let bRightMin = (j < b.length ? b[j] : Number.POSITIVE_INFINITY);

    if (totalLen % 2 === 1) {
        // Odd total length → median is the maximum of the left side
        return Math.max(aLeftMax, bLeftMax);
    } else {
        // Even total length → median is average of max left and min right
        return (Math.max(aLeftMax, bLeftMax) + Math.min(aRightMin, bRightMin)) / 2;
    }
}
